PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS access_roles (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, permissions_json TEXT NOT NULL, built_in INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('administrator','supervisor','quality_analyst','viewer')), enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', first_name TEXT NOT NULL DEFAULT '', last_name TEXT NOT NULL DEFAULT '', nickname TEXT NOT NULL DEFAULT '', job_title TEXT NOT NULL DEFAULT '', division TEXT NOT NULL DEFAULT '', department TEXT NOT NULL DEFAULT '', access_role_id TEXT REFERENCES access_roles(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS connections (id TEXT PRIMARY KEY, name TEXT NOT NULL, organization_label TEXT NOT NULL, region_id TEXT NOT NULL, api_base_url TEXT NOT NULL, oauth_base_url TEXT NOT NULL, client_id TEXT NOT NULL, client_secret_enc TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, is_default INTEGER NOT NULL DEFAULT 0, last_success_at TEXT, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_connection_access (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE CASCADE, PRIMARY KEY(user_id,connection_id));
CREATE TABLE IF NOT EXISTS bot_flow_registry (id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE CASCADE, flow_id TEXT, flow_name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'voice_bot');
CREATE TABLE IF NOT EXISTS saved_searches (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, filters_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS search_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, preferences_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS user_appearance (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, appearance_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customer_field_mappings (id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE CASCADE, field_name TEXT NOT NULL, source_type TEXT NOT NULL, source_key TEXT NOT NULL, sensitive INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS conversation_metadata_index (connection_id TEXT NOT NULL, conversation_id TEXT NOT NULL, indexed_at TEXT NOT NULL, expires_at TEXT NOT NULL, metadata_json TEXT NOT NULL, PRIMARY KEY(connection_id,conversation_id));
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, username TEXT NOT NULL, action TEXT NOT NULL, result TEXT NOT NULL, connection_id TEXT, conversation_id TEXT, recording_id TEXT, source_ip TEXT, detail_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_logs(created_at DESC);
CREATE TABLE IF NOT EXISTS application_settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS library_destinations (id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('local','sftp','ftp','smb')), config_enc TEXT NOT NULL, created_by TEXT REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS library_schedules (id TEXT PRIMARY KEY, name TEXT NOT NULL, connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE CASCADE, destination_id TEXT NOT NULL REFERENCES library_destinations(id) ON DELETE RESTRICT, cadence TEXT NOT NULL CHECK(cadence IN ('daily','weekly','monthly')), day_of_week INTEGER, day_of_month INTEGER, run_time TEXT NOT NULL DEFAULT '02:00', time_zone TEXT NOT NULL DEFAULT 'Asia/Bangkok', lookback_days INTEGER NOT NULL DEFAULT 550, enabled INTEGER NOT NULL DEFAULT 1, cursor_at TEXT NOT NULL, backfill_complete INTEGER NOT NULL DEFAULT 0, next_run_at TEXT NOT NULL, run_status TEXT NOT NULL DEFAULT 'queued' CHECK(run_status IN ('queued','running','idle','failed')), run_requested INTEGER NOT NULL DEFAULT 0, last_started_at TEXT, last_finished_at TEXT, last_error TEXT, created_by TEXT REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS library_archive_queue (id INTEGER PRIMARY KEY AUTOINCREMENT, schedule_id TEXT NOT NULL REFERENCES library_schedules(id) ON DELETE CASCADE, conversation_id TEXT NOT NULL, conversation_start TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','failed')), attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TEXT NOT NULL, UNIQUE(schedule_id,conversation_id));
CREATE TABLE IF NOT EXISTS archived_recordings (id TEXT PRIMARY KEY, connection_id TEXT NOT NULL, conversation_id TEXT NOT NULL, recording_id TEXT NOT NULL, destination_id TEXT NOT NULL REFERENCES library_destinations(id) ON DELETE RESTRICT, relative_path TEXT NOT NULL, file_name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, conversation_start TEXT NOT NULL, conversation_end TEXT, direction TEXT NOT NULL DEFAULT '', ani TEXT NOT NULL DEFAULT '', dnis TEXT NOT NULL DEFAULT '', agent_names TEXT NOT NULL DEFAULT '', flows TEXT NOT NULL DEFAULT '[]', queues TEXT NOT NULL DEFAULT '', interaction_type TEXT NOT NULL DEFAULT 'Unknown', duration_ms INTEGER, metadata_json TEXT NOT NULL, archived_at TEXT NOT NULL, expires_at TEXT NOT NULL, UNIQUE(connection_id,conversation_id,recording_id));
CREATE TABLE IF NOT EXISTS recording_playability (connection_id TEXT NOT NULL, conversation_id TEXT NOT NULL, recording_id TEXT NOT NULL, is_unplayable INTEGER NOT NULL DEFAULT 1 CHECK(is_unplayable IN (0,1)), marked_by TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(connection_id,conversation_id,recording_id));
CREATE INDEX IF NOT EXISTS library_archive_search_idx ON archived_recordings(conversation_start DESC, archived_at DESC);
CREATE INDEX IF NOT EXISTS library_archive_conversation_idx ON archived_recordings(connection_id,conversation_id);
CREATE INDEX IF NOT EXISTS library_queue_pending_idx ON library_archive_queue(schedule_id,status,conversation_start);
